{
  "status": "SUPPORTED",
  "task_summary": "Find compatible parts and tools, fasten them at a specific spot on the workbench, then put the tool back on the desk.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The part that needs to be fastened.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["part", "hardware", "connector"],
        "required_properties": ["compatible_with_target_location"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to secure the component.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["tool", "device", "instrument"],
        "required_properties": ["capable_of_fastening"]
      },
      {
        "id": "target_location",
        "entity_kind": "REGION",
        "function": "The specific spot on the workbench where fastening occurs.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["surface", "slot", "attachment_point"]
      ,
      "required_properties": []
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the tool is left after the task.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "surface"],
        "required_properties": []
      }
    ],
    "functional_relations": [
      {
        "id": "fits",
        "relation": "The compatible component must fit the target location.",
        "participant_roles": ["compatible_component", "target_location"]
      ,
        "required": true
      },
      {
        "id": "used_for",
        "relation": "The fastening tool is used on the compatible component.",
        "participant_roles": ["fastening_tool", "compatible_component"]
      ,
        "required": true
      },
      {
        "id": "placed_on",
        "relation": "The fastening tool ends up on the workbench.",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_components",
        "operation": "Locate the compatible component relative to the target location.",
        "participant_roles": ["compatible_component", "target_location"],
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "Secure the component at the target location using the tool.",
        "participant_roles": ["fastening_tool", "compatible_component", "target_location"],
        "operation_count": 1
      },
      {
        "id": "place_equipment",
        "operation": "Put the tool down on the workbench.",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "compatible_component": [
        {
          "label": "Yellow/blue object on tray",
          "visual_description": "A yellow and blue rectangular object sitting on a black tray on the workbench."
        }
      ],
      "fastening_tool": [
        {
          "label": "Tray object",
          "visual_description": "Likely the same yellow/blue object on the tray, possibly a stapler or clamp."
        }
      ],
      "target_location": [
        {
          "label": "Workbench surface",
          "visual_description": "The wooden surface of the table."
        }
      ],
      "workbench": [
        {
          "label": "Wooden table",
          "visual_description": "A wooden desk with drawers and a blue cabinet on top."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "Left drawer",
        "visual_description": "A closed blue drawer underneath the left side of the workbench.",
        "reason": "Closed storage structure that could contain components or tools."
      },
      {
        "id": "right_drawer",
        "label": "Right drawer",
        "visual_description": "A closed blue drawer underneath the right side of the workbench.",
        "reason": "Closed storage structure that could contain components or tools."
      },
      {
        "id": "desk_cabinet",
        "label": "Desk cabinet",
        "visual_description": "A blue cabinet sitting on the right side of the workbench with a handle.",
        "reason": "Closed storage structure that could contain components or tools."
      },
      {
        "id": "background_cabinet",
        "label": "Background cabinet",
        "visual_description": "A grey cabinet or shelf unit located behind the workbench.",
        "reason": "Closed storage structure that could contain components or tools."
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "desk_cabinet",
      "background_cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
